internal static class Program
{
    [DllImport("user32.dll")]private static extern bool SetForegroundWindow(IntPtr window);
    [DllImport("user32.dll")]private static extern bool ShowWindow(IntPtr window,int command);
    [STAThread]private static int Main(string[] args)
    {
        try {
            Loc.Set(Preferences.Load().Language);
            int languageImport=Array.IndexOf(args,"--import-language");
            if(languageImport>=0&&languageImport+1<args.Length){string id=LanguagePacks.Import(args[languageImport+1]);var settings=Preferences.Load();settings.Language=id;settings.Save();NativeConfig.Write(settings);return 0;}
            int languageExport=Array.IndexOf(args,"--export-language-kit");
            if(languageExport>=0&&languageExport+1<args.Length){LanguagePacks.ExportKit(args[languageExport+1]);return 0;}
            if(args.Contains("--test-language-packs"))return LanguagePackChecks.Run(false);
            if(args.Contains("--test-language-packs-worker"))return LanguagePackChecks.Run(true);
            if(args.Contains("--test-localization")){Loc.Check();return 0;}
            if(args.Contains("--defaults")){NativeConfig.Write(new Preferences());return 0;}
            if(args.Contains("--self-test")){Loc.Check();Game.Validate();GameLanguages.Validate(Preferences.Load().Language);return 0;}
            if(args.Contains("--test-services"))return ServiceChecks.Run();
            if(args.Contains("--verify-files")){var errors=Game.Verify();Files.Atomic(System.IO.Path.Combine(Files.Docs,"son_denetim.json"),Files.Json.Serialize(new{passed=errors.Count==0,errors=errors}));return errors.Count==0?0:1;}
            if(args.Contains("--test-game"))return Game.Run(Preferences.Load(),true);
            bool bilingual=args.Contains("--render-bilingual");bool render=args.Contains("--render-ui")||bilingual;string identity=Files.Hash(System.Reflection.Assembly.GetExecutingAssembly().Location).Substring(0,12)+Files.Root.GetHashCode().ToString("X");
            bool owned;using(var mutex=new Mutex(true,@"Local\PatriotsMGSM_"+identity,out owned)){
                if(!owned&&!render){FocusOther();return 0;}
                try{
                    var settings=Preferences.Load();if(!render&&(args.Contains("--play")||(settings.DirectPlay&&!args.Contains("--ayarlar"))))return settings.ShowBrand?DirectSplash.Run(settings):Game.Run(settings);
                    var app=new Application{ShutdownMode=ShutdownMode.OnMainWindowClose};var window=new PatriotsWindow();app.MainWindow=window;
                    if(render){window.ShowInTaskbar=false;window.Left=-25000;window.Top=-25000;window.Loaded+=(o,e)=>window.Dispatcher.BeginInvoke(new Action(()=>{if(bilingual)window.RenderBilingual();else window.RenderPreviews();app.Shutdown();}),DispatcherPriority.ApplicationIdle);}
                    app.Run(window);return 0;
                }finally{if(owned)mutex.ReleaseMutex();}
            }
        }catch(Exception error){Files.Log("ERROR "+error);if(args.Any(a=>a.StartsWith("--test")||a.StartsWith("--verify")||a.StartsWith("--import-language")||a.StartsWith("--export-language-kit")||a=="--self-test"||a=="--render-ui"))return 1;MessageBox.Show(error.Message,"Patriots · Metal Gear Solid Mobile",MessageBoxButton.OK,MessageBoxImage.Error);return 1;}
    }
    private static void FocusOther(){using(var current=Process.GetCurrentProcess())foreach(var process in Process.GetProcessesByName(current.ProcessName))using(process){try{if(process.Id==current.Id||!String.Equals(process.MainModule.FileName,current.MainModule.FileName,StringComparison.OrdinalIgnoreCase))continue;if(process.MainWindowHandle!=IntPtr.Zero){ShowWindow(process.MainWindowHandle,9);SetForegroundWindow(process.MainWindowHandle);return;}}catch{}}foreach(var process in Process.GetProcessesByName("mgs_mobile"))using(process)try{if(String.Equals(process.MainModule.FileName,System.IO.Path.Combine(Files.Engine,"mgs_mobile.exe"),StringComparison.OrdinalIgnoreCase))SetForegroundWindow(process.MainWindowHandle);}catch{}}
}

