    private void CopyKeys(List<ActionBinding> defaults){foreach(var b in model.Bindings){var d=defaults.First(x=>x.Id==b.Id);b.Key1=d.Key1;b.Key2=d.Key2;}Changed();}
    private Border InputRow(string label,UIElement one,UIElement two,bool header=false){var row=new Grid{MinHeight=header?32:54};row.ColumnDefinitions.Add(new ColumnDefinition());row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(228)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(228)});var name=T(label,header?10:13,header?Muted:Ink);name.VerticalAlignment=VerticalAlignment.Center;row.Children.Add(name);var left=new Border{Margin=new Thickness(0,5,12,5),Child=one};Grid.SetColumn(left,1);row.Children.Add(left);var right=new Border{Margin=new Thickness(0,5,0,5),Child=two};Grid.SetColumn(right,2);row.Children.Add(right);return new Border{BorderBrush=Line,BorderThickness=new Thickness(0,0,0,1),Child=row};}
    private void Capture(ActionBinding b,int slot){var w=new Window{Owner=this,Title=Loc.T("Tuş ata"),Width=470,Height=242,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=Paper,FontFamily=FontFamily,ShowInTaskbar=false};var p=new StackPanel{Margin=new Thickness(28)};p.Children.Add(T(b.Label,21));var hint=T(Loc.T("Atamak istediğin tuşa bas."),13,Muted);hint.Margin=new Thickness(0,17,0,22);p.Children.Add(hint);var actions=new WrapPanel();actions.Children.Add(Button(Loc.T("Temizle"),()=>{if(slot==1)b.Key1=0;else b.Key2=0;Changed();w.Close();}));actions.Children.Add(Button(Loc.T("Vazgeç"),()=>w.Close()));p.Children.Add(actions);w.Content=p;
        w.PreviewKeyDown+=(o,e)=>{int vk=KeyInterop.VirtualKeyFromKey(e.Key==Key.System?e.SystemKey:e.Key);if(vk==112||vk==116||vk==123){hint.Text=Loc.T("Bu tuş oyuna ayrılmış. Başka bir tuş seç.");e.Handled=true;return;}if(vk>=160&&vk<=161)vk=16;if(vk>=162&&vk<=163)vk=17;if(vk>=164&&vk<=165)vk=18;if(vk<1||vk>255)return;if(slot==1)b.Key1=vk;else b.Key2=vk;Changed();e.Handled=true;w.Close();};w.ShowDialog();ShowPage("controls");
    }
    private void PollPad(){if(running||active!="controls"||controlTab!="pad"||padState==null)return;bool connected=pad.Poll(testPad);padState.Text=connected?(pad.Pressed.Count==0?Loc.T("Bağlı · tuş bekleniyor"):String.Join("  ·  ",pad.Pressed.Select(k=>Inputs.Pads.ContainsKey(k)?Inputs.PadName(k):(k==4?"Back / Share":k==8?Loc.T("Sağ çubuk"):Loc.T("Tuş ")+k)))):Loc.T("Kontrolcü bağlantısı bekleniyor");
        padValues.Text=connected?String.Format(Loc.T("SOL  {0:+0.00;-0.00;0.00} / {1:+0.00;-0.00;0.00}     SAĞ  {2:+0.00;-0.00;0.00} / {3:+0.00;-0.00;0.00}     LT {4:0.00}   RT {5:0.00}"),pad.Axes.Cast<object>().ToArray()):pad.Error??"";padDrawing.Children.Clear();for(int i=0;i<2;i++){double x=9+i*150;var circle=new Ellipse{Width=88,Height=88,Fill=B("#E1E6D8"),Stroke=B("#A2AD93"),StrokeThickness=1};Canvas.SetLeft(circle,x);Canvas.SetTop(circle,3);padDrawing.Children.Add(circle);var dot=new Ellipse{Width=14,Height=14,Fill=Green};Canvas.SetLeft(dot,x+37+pad.Axes[i*2]*32);Canvas.SetTop(dot,40+pad.Axes[i*2+1]*32);padDrawing.Children.Add(dot);var text=Small(i==0?Loc.T("SOL ANALOG"):Loc.T("SAĞ ANALOG"));Canvas.SetLeft(text,x+7);Canvas.SetTop(text,98);padDrawing.Children.Add(text);}}
    private void Sound(){var p=Page("03",Loc.T("Ses ve Discord"),Loc.T("Ses düzeyini ve Discord profilinde gösterilecek oyun bilgilerini ayarla."));var volume=new StackPanel();var number=T(model.Volume+" / 100",13);number.HorizontalAlignment=HorizontalAlignment.Right;volume.Children.Add(number);var slider=new Slider{Minimum=0,Maximum=100,Value=model.Volume,TickFrequency=1,IsSnapToTickEnabled=true,Margin=new Thickness(0,8,0,0)};slider.ValueChanged+=(o,e)=>{model.Volume=(int)slider.Value;number.Text=model.Volume+" / 100";Changed();};volume.Children.Add(slider);Field(p,Loc.T("Ana ses"),Loc.T("Oyunun Windows ses oturumuna uygulanır."),volume);Field(p,Loc.T("Sessize al"),Loc.T("Seçtiğin ses düzeyi saklanır."),Switch(model.Mute,v=>model.Mute=v));Section(p,"Discord Rich Presence",Loc.T("Oda, oyun durumu ve oturum süresi Discord profilinde görünür."));Field(p,Loc.T("Discord etkinliği"),Loc.T("Discord masaüstü uygulaması açıkken otomatik bağlanır."),Switch(model.DiscordPresence,v=>model.DiscordPresence=v));Field(p,Loc.T("Oda bilgisini göster"),Loc.T("Kapalıyken yalnızca genel oyun durumu paylaşılır."),Switch(model.DiscordRoom,v=>model.DiscordRoom=v));Section(p,Loc.T("Oyun içindeki ses seçenekleri"));var note=T(Loc.T("Oyunun kendi menüsündeki ses ayarları da geçerlidir. Çıkış aygıtı Windows'un seçili ses aygıtıdır."),13,Muted);note.MaxWidth=650;note.HorizontalAlignment=HorizontalAlignment.Left;p.Children.Add(note);}
    private void SavesPage(){var p=Page("04",Loc.T("Kayıtlar ve başlatıcı"),Loc.T("Kayıtlarını koru, ayarlarını taşı ve oyun dosyalarını denetle."));Section(p,Loc.T("Oyun kayıtları"));Field(p,Loc.T("Otomatik kayıt yedeği"),Loc.T("Oyun açılmadan önce mevcut kayıtların bir kopyasını alır."),Switch(model.AutoBackup,v=>model.AutoBackup=v));var actions=new WrapPanel{Margin=new Thickness(0,16,0,0)};actions.Children.Add(Button(Loc.T("Şimdi yedekle"),()=>{Stopped();string result=Saves.Create();Notice(result==null?Loc.T("Henüz yedeklenecek bir oyun kaydı yok."):Loc.T("Kayıt yedeği oluşturuldu.\n")+result);}));actions.Children.Add(Button(Loc.T("Geri yükle"),Restore));actions.Children.Add(Button(Loc.T("Yedek klasörü"),()=>OpenFolder(Files.Backups)));p.Children.Add(actions);Section(p,Loc.T("Tercihler"));var prefs=new WrapPanel();prefs.Children.Add(Button(Loc.T("Ayarları dışa aktar"),Export));prefs.Children.Add(Button(Loc.T("Ayarları içe aktar"),Import));prefs.Children.Add(Button(Loc.T("Varsayılanlara dön"),Reset));p.Children.Add(prefs);Field(p,Loc.T("Oynarken başlatıcıyı gizle"),Loc.T("Oyun kapandığında bu pencereye dönersin."),Switch(model.HideLauncher,v=>model.HideLauncher=v));Field(p,Loc.T("EXE'den doğrudan oyna"),Loc.T("Ayarlar.cmd dosyası her zaman başlatıcıyı açar."),Switch(model.DirectPlay,v=>model.DirectPlay=v));Section(p,Loc.T("Dosyalar"));var files=new WrapPanel();files.Children.Add(Button(Loc.T("Oyun dosyalarını doğrula"),async()=>await Verify()));files.Children.Add(Button(Loc.T("Oyun klasörü"),()=>OpenFolder(Files.Root)));files.Children.Add(Button(Loc.T("Belgeler"),()=>OpenFolder(Files.Docs)));p.Children.Add(files);var footer=T(Loc.T("Kayıt geri yükleme için oyunun kapalı olması gerekir. Geri yüklemeden önce mevcut kayıtların ayrıca yedeklenir."),11,Muted);footer.Margin=new Thickness(0,20,0,0);p.Children.Add(footer);}
    private void Stopped(){if(running||Game.Pid!=0)throw new InvalidOperationException(Loc.T("Bu işlem için önce oyunu kapat."));}
    private void OpenFolder(string path){Directory.CreateDirectory(path);Process.Start(new ProcessStartInfo(path){UseShellExecute=true});}
    private void Restore(){Stopped();var d=new OpenFileDialog{Filter=Loc.T("MGS kayıt yedeği|*.zip"),InitialDirectory=Files.Backups};if(d.ShowDialog(this)!=true)return;if(MessageBox.Show(this,Loc.T("Seçili yedek, mevcut oyun kayıtlarının üzerine yazılacak. Mevcut kayıtlar önce yedeklenecek. Devam edilsin mi?"),Loc.T("Kayıtları geri yükle"),MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;Saves.Create();Notice(Saves.Restore(d.FileName)+Loc.T(" kayıt dosyası geri yüklendi."));}
    private void LanguagesPage(){
        var p=Page("05",Loc.T("Diller ve çeviri paketleri"),Loc.T("Launcher veya oyun çevirisini JSON olarak içe aktar."));
        var actions=new WrapPanel();actions.Children.Add(Button(Loc.T("Dil paketi içe aktar"),ImportLanguage,true));
        actions.Children.Add(Button(Loc.T("Çeviri şablonlarını dışa aktar"),ExportLanguages));
        actions.Children.Add(Button(Loc.T("Çeviri klasörü"),()=>OpenFolder(System.IO.Path.Combine(Files.Root,"Translations"))));p.Children.Add(actions);
        Section(p,Loc.T("Kurulu diller"));
        foreach(var lang in LanguagePacks.Available()){
            string details=Loc.T(lang.official?"Resmî":"Topluluk")+" · "+Loc.T("Launcher")+": "+(lang.official?Loc.T("Açık"):lang.launcher?lang.launcherTranslated+" / "+lang.launcherTotal:Loc.T("İngilizce yedek dil"))+" · "+Loc.T("Oyun")+": "+(lang.official?Loc.T("Açık"):lang.game?lang.gameTranslated+" / "+lang.gameTotal:Loc.T("İngilizce yedek dil"));
            if(!String.IsNullOrWhiteSpace(lang.author))details+="\n"+lang.author;
            Field(p,lang.native_name+"  ("+lang.id+")",details,Button(Loc.T("Dil"),()=>ChangeLanguage(lang.id,true)));
        }
        p.Children.Add(T(Loc.T("Yalnızca launcher çevirisi kurulduysa oyun İngilizce açılır. Oyun çevirisini aynı dil koduyla daha sonra ekleyebilirsin."),12,Muted));
        var note=T(Loc.T("Sadece text alanlarını çevir. id, source ve korunan işaretlere dokunma."),12,Muted);note.Margin=new Thickness(0,14,0,0);p.Children.Add(note);
    }
    private void ImportLanguage(){Stopped();var d=new OpenFileDialog{Filter=Loc.T("Dil paketleri|*.json;*.zip")};if(d.ShowDialog(this)!=true)return;string id=LanguagePacks.Import(d.FileName);ChangeLanguage(id,true,true);ShowPage("languages");Notice(Loc.T("Dil paketi kuruldu."));}
    private void ExportLanguages(){using(var d=new System.Windows.Forms.FolderBrowserDialog{Description=Loc.T("Dışa aktarım klasörünü seç.")}){if(d.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return;LanguagePacks.ExportKit(d.SelectedPath);Notice(Loc.T("Çeviri şablonları dışa aktarıldı."));}}
    private void Export(){var d=new SaveFileDialog{FileName=Loc.T("Patriots_MGS_Ayarlar.json"),Filter=Loc.T("Ayar dosyası|*.json")};if(d.ShowDialog(this)==true)Files.Atomic(d.FileName,Files.Json.Serialize(model));}
    private void Import(){var d=new OpenFileDialog{Filter=Loc.T("Ayar dosyası|*.json")};if(d.ShowDialog(this)!=true)return;var imported=Files.Json.Deserialize<Preferences>(File.ReadAllText(d.FileName));imported.Validate();imported.PlaySeconds=model.PlaySeconds;imported.LastPlayed=model.LastPlayed;var importedLanguage=imported.Language;imported.Language=model.Language;model=imported;ChangeLanguage(importedLanguage,true);Changed();ShowPage(active);}
    private void Reset(){if(MessageBox.Show(this,Loc.T("Başlatıcı ve kontrol ayarları varsayılana dönecek. Oyun kayıtları korunur. Devam edilsin mi?"),Loc.T("Ayarları sıfırla"),MessageBoxButton.YesNo)!=MessageBoxResult.Yes)return;model=new Preferences{Language=model.Language,PlaySeconds=model.PlaySeconds,LastPlayed=model.LastPlayed};Changed();ShowPage(active);}
    private async Task Verify(){try{Stopped();state.Text=Loc.T("●  DOSYALAR DENETLENİYOR");var failures=await Task.Run(()=>Game.Verify((done,total)=>Dispatcher.BeginInvoke(new Action(()=>status.Text=done+" / "+total+Loc.T(" dosya doğrulandı")))));Notice(failures.Count==0?Loc.T("Tüm oyun dosyaları doğrulandı."):Loc.T("Eksik veya değişmiş dosyalar:\n")+String.Join("\n",failures.Take(25)));state.Text=failures.Count==0?Loc.T("●  DOSYALAR DOĞRULANDI"):Loc.T("●  DENETİM TAMAMLANDI");}catch(Exception e){Notice(e.Message,true);}}
    private bool Save(bool notify){try{if(running){model.Save();NativeConfig.WriteLiveControls(model);}else NativeConfig.Write(model);dirty=false;save.IsEnabled=false;state.Text=Loc.T("●  AYARLAR KAYDEDİLDİ");status.Text=running?Loc.T("Ses ve kontroller anında uygulanır; görüntü ayarları sonraki açılışta geçerli"):Loc.T("Göreve hazırsın · F5 ile oyna");ShowPage(active);if(notify)Notice(running?Loc.T("Kaydedildi. Ses, tuş atamaları ve Discord ayarları anında uygulanır. Görüntü ayarları sonraki açılışta geçerli."):Loc.T("Ayarlar kaydedildi."));return true;}catch(Exception e){Notice(e.Message,true);return false;}}
    private async void StartGame(){if(running||!Save(false))return;running=true;play.Content=Loc.T("OYUNA DÖN  ↗");state.Text=Loc.T("●  OYUN ÇALIŞIYOR");status.Text=Loc.T("İyi oyunlar.");pad.Dispose();try{if(model.ShowBrand){busy.Visibility=Visibility.Visible;await Task.Delay(1400);busy.Visibility=Visibility.Collapsed;}if(model.HideLauncher)Hide();int exit=await Task.Run(()=>Game.Run(model));if(exit!=0)Notice(Loc.T("Oyun kapandı. Çıkış kodu: ")+exit+Loc.T("\nAyrıntılar Oyun/mgs_mobile.log dosyasında."),true);}catch(Exception ex){Notice(ex.Message,true);}finally{running=false;busy.Visibility=Visibility.Collapsed;var latest=Preferences.Load();if(dirty){model.PlaySeconds=latest.PlaySeconds;model.LastPlayed=latest.LastPlayed;}else model=latest;pad=new PadProbe();play.Content=Loc.T("OYNA     ↗");Show();Activate();state.Text=Loc.T("●  OYUN HAZIR");status.Text=Loc.T("Tekrar göreve dönmeye hazır");ShowPage(active);}}
    private void About(){MessageBox.Show(this,Loc.T("METAL GEAR SOLID MOBILE\nPATRIOTS TÜRKÇE SÜRÜM · 5.0\n\nTürkçe yama ve başlatıcı: Patriots Çeviri\nOyun altyapısı: LeithSilver/mgsm v0.1\nÖzgün oyun: Konami / Ideaworks3D, 2008\n\nPatriots logosu resmî siteden alınmıştır.\nTeknik bilgiler ve lisanslar Belgeler klasöründedir.").Replace("5.0","5.3"),"Patriots Çeviri",MessageBoxButton.OK,MessageBoxImage.Information);}
    private void Notice(string text,bool error=false){MessageBox.Show(this,text,"Patriots · Metal Gear Solid Mobile",MessageBoxButton.OK,error?MessageBoxImage.Error:MessageBoxImage.Information);}
    public void RenderBilingual(){var original=model.Language;foreach(var language in new[]{"tr","en","tr"}){ChangeLanguage(language,false);Loc.Check();if(model.Language!=language||Loc.Language!=language)throw new Exception("Language switch failed");RenderPreviews();}ChangeLanguage(original,false);Files.Atomic(System.IO.Path.Combine(Files.Docs,"dil_arayuz_testi.json"),"{\"passed\":true,\"switches\":[\"tr\",\"en\",\"tr\"]}");}
    public void RenderPreviews(){string folder=System.IO.Path.Combine(Files.Docs,"Onizleme",model.Language);Directory.CreateDirectory(folder);foreach(string id in new[]{"home","display","controls","sound","saves","languages"}){ShowPage(id);UpdateLayout();Render(folder,id);}displayTab="quality";ShowPage("display");UpdateLayout();Render(folder,"quality");displayTab="game";ShowPage("display");UpdateLayout();Render(folder,"gameplay");controlTab="pad";ShowPage("controls");PollPad();UpdateLayout();Render(folder,"controller");busy.Visibility=Visibility.Visible;UpdateLayout();Render(folder,"startup");busy.Visibility=Visibility.Collapsed;}
    private void Render(string folder,string name){var bitmap=new RenderTargetBitmap((int)layout.ActualWidth,(int)layout.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(layout);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(System.IO.Path.Combine(folder,name+".png")))png.Save(file);}
