internal static class DirectSplash
{
    public static int Run(Preferences settings){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};var window=new Window{Title="Patriots Çeviri",Width=390,Height=340,WindowStyle=WindowStyle.None,ResizeMode=ResizeMode.NoResize,WindowStartupLocation=WindowStartupLocation.CenterScreen,Background=(Brush)new BrushConverter().ConvertFromString("#101712"),ShowInTaskbar=false};
        var p=new StackPanel{VerticalAlignment=VerticalAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center};var image=new Image{Source=new BitmapImage(new Uri(System.IO.Path.Combine(Files.Assets,"patriots.jpg"))),Stretch=Stretch.Uniform};p.Children.Add(new Border{Width=144,Height=144,CornerRadius=new CornerRadius(72),Background=Brushes.White,Padding=new Thickness(14),Clip=new EllipseGeometry(new Rect(0,0,144,144)),Child=image});p.Children.Add(new TextBlock{Text="PATRIOTS ÇEVİRİ",FontSize=15,Foreground=(Brush)new BrushConverter().ConvertFromString("#D5EB72"),HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,24,0,10)});p.Children.Add(new TextBlock{Text=Loc.T("GÖREVE HAZIRLANIYOR"),FontSize=10,Foreground=Brushes.LightGray,HorizontalAlignment=HorizontalAlignment.Center});window.Content=p;app.MainWindow=window;
        window.Loaded+=async(o,e)=>{try{await Task.Delay(1400);window.Hide();int code=await Task.Run(()=>Game.Run(settings));app.Shutdown(code);}catch(Exception ex){Files.Log("DIRECT_ERROR "+ex);MessageBox.Show(ex.Message,"Patriots · MGS Mobile");app.Shutdown(1);}};return app.Run(window);
    }
}

internal static class ServiceChecks
{
    public static int Run(){var log=new List<string>();string originalIni=File.Exists(Files.Ini)?File.ReadAllText(Files.Ini):null,originalPrefs=File.Exists(Files.Preferences)?File.ReadAllText(Files.Preferences):null;string live=System.IO.Path.Combine(Files.Engine,"patriots_live.ini"),originalLive=File.Exists(live)?File.ReadAllText(live):null;string fixture=System.IO.Path.Combine(Files.Assets,"test_"+Guid.NewGuid().ToString("N"));
        try{var prefs=new Preferences{Fov=125,Msaa=4,Scale=2,Analog=true,CrispUI=false,InvertInventoryScroll=true,Fullscreen=false,Width=1600,Height=900,Volume=43};NativeConfig.Write(prefs);var loaded=Preferences.Load();if(loaded.CrispUI||!loaded.InvertInventoryScroll||loaded.Fov!=125||loaded.Msaa!=4||loaded.Scale!=2||!loaded.Analog||loaded.Fullscreen||loaded.Width!=1600||loaded.Volume!=43||loaded.Bindings.First(b=>b.Id=="up").Key1!=87)throw new Exception("Native ayar aktarımı doğrulanamadı.");log.Add("PASS: native INI, launcher JSON and keyboard/gamepad binding round trip");
            NativeConfig.WriteLiveControls(prefs);if(!File.ReadAllText(live).Contains("invert_inventory_scroll=1"))throw new Exception("Live inventory preference was not written");var legacy=Files.Json.Deserialize<Preferences>("{\"Version\":6,\"Language\":\"en\"}");if(!legacy.CrispUI||legacy.InvertInventoryScroll)throw new Exception("Legacy preference defaults failed");log.Add("PASS: crisp UI/inventory INI round trip, live command and v5.1 preference defaults");
            Directory.CreateDirectory(fixture);string save=System.IO.Path.Combine(fixture,"savedata.i3d");File.WriteAllText(save,"Patriots save round trip",Encoding.UTF8);string hash=Files.Hash(save);string zip=Saves.Create(fixture,fixture);File.WriteAllText(save,"modified");if(Saves.Restore(zip,fixture)!=1||Files.Hash(save)!=hash)throw new Exception("Kayıt yedeği döngüsü başarısız.");log.Add("PASS: isolated save backup/restore; no user saves touched");
            using(var probe=new PadProbe()){var devices=probe.Devices();if(!probe.Ready)throw new Exception("SDL3 controller initialization failed: "+probe.Error);log.Add("PASS: SDL3 initialized; devices="+String.Join("; ",devices.Values));}
            Files.Atomic(System.IO.Path.Combine(Files.Docs,"baslatici_testleri.txt"),String.Join("\n",log));return 0;
        }catch(Exception ex){log.Add("FAIL: "+ex);Files.Atomic(System.IO.Path.Combine(Files.Docs,"baslatici_testleri.txt"),String.Join("\n",log));return 1;}
        finally{if(originalLive==null){if(File.Exists(live))File.Delete(live);}else Files.Atomic(live,originalLive);if(originalIni==null){if(File.Exists(Files.Ini))File.Delete(Files.Ini);}else Files.Atomic(Files.Ini,originalIni);if(originalPrefs==null){if(File.Exists(Files.Preferences))File.Delete(Files.Preferences);}else Files.Atomic(Files.Preferences,originalPrefs);if(Directory.Exists(fixture)){foreach(string file in Directory.GetFiles(fixture))File.Delete(file);Directory.Delete(fixture);}}
    }
}
